"""Teacher-edited thermal revision spine. Run to generate sheets.json; originals untouched."""
from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parent
pages=[]
def C(title,eqs,text,why,trap):
 return dict(title=title,items=[*[('m',x) for x in eqs],('p',text),('why',why),('trap',trap)])
def P(part,slug,title,sub,source,diagrams,remember,*cards):
 n=1+sum(p['section']==part for p in pages)
 assert len(cards)==4
 pages.append(dict(section=part,part_page=n,slug=f'{part}/{n:02}-{slug}',title=title,subtitle=sub,source=source,diagrams=diagrams,takeaway=remember,cards=cards))
def J(*args):P('JEE',*args)
def O(*args):P('Olympiad',*args)
J('temperature','Temperature & equilibrium','Choose the system boundary. Absolute T belongs in gas laws, ratios, radiation and entropy.','Source §§1.1-1.3, 3.1; formula sheet',['equilibrium','thermometer'],'Equal temperature means thermal equilibrium, not equal internal energy or equal molecular speed.',
C('Zeroth law makes T measurable',[r'T_A=T_C,\ T_B=T_C\ \Rightarrow\ T_A=T_B'],'If A and B separately reach thermal equilibrium with C, they are in thermal equilibrium with each other. C can act as a thermometer. The law establishes a consistent way to compare temperatures.','Equilibrium means zero NET heat transfer. Microscopic energy exchanges can continue in both directions at equal rates.','A diathermal wall transfers energy, not necessarily molecules. A material barrier and a thermal barrier are distinct constraints.'),
C('System, state & constraints',[],'Closed: fixed matter, energy may cross. Isolated: neither matter nor energy crosses. Open: matter carries energy across the boundary. Equilibrium states have well-defined macroscopic variables; a process connects such states.','Thermal, mechanical and chemical equilibrium are separate. A loaded piston can maintain unequal pressures while it is in mechanical equilibrium.','Adiabatic means no heat transfer, not no work, no temperature change or no entropy generation. Quasistatic alone is not reversible.'),
C('Scales and calibration',[r'T(\mathrm K)=t(^{\circ}\mathrm C)+273.15',r't_F=\frac95t_C+32,\quad\Delta t_F=\frac95\Delta t_C',r'\frac{t-t_1}{t_2-t_1}=\frac{X-X_1}{X_2-X_1}'],'The last relation calibrates a thermometric property X that varies linearly with temperature over the stated range. Use two fixed points to find offset and slope.','A temperature increment has the same numerical value in K and Celsius; temperature values themselves do not.','Do not use Celsius in temperature ratios or a linear calibration outside its validity range.'),
C('Gas thermometer & symbols',[r'PV=nRT=Nk_BT,\quad N=nN_A',r'R=N_Ak_B=8.314\ \mathrm{J\,mol^{-1}K^{-1}}'],'At fixed volume, ideal-gas pressure is proportional to absolute temperature. Low-density extrapolation gives gas-independent thermometry. n=moles, N=molecules, nu=N/V number density, M=molar mass in kg/mol, rho=mass density.','kB T is energy per particle; RT is energy per mole. This distinction keeps microscopic and macroscopic formulas consistent.','Use s for the polytropic exponent, not n. Never combine molecular mass with R or molar mass with kB.'))
J('expansion','Expansion: geometry & constraint','Uniform heating, isotropic material, small temperature changes unless a different model is stated.','Source §§1.3-1.7; clock, tyre and bimetal examples',['hole','bimetal'],'A hole expands with its plate. Thermal stress appears when free thermal expansion is restricted.',
C('One scale factor, three measures',[r'\Delta L=\alpha L_0\Delta T',r'\beta_A\simeq2\alpha,\quad\beta_V\simeq3\alpha',r'\Delta V=\beta_VV_0\Delta T'],'Alpha, beta(A) and beta(V) are linear, area and volume coefficients, all in 1/K. These are first-order approximations for uniform isotropic expansion.','All lengths scale by 1+alpha delta T. Square or cube that factor and retain first-order terms to obtain the other coefficients.','If alpha varies significantly, integrate dL/L=alpha(T)dT. Large changes need not obey a constant-coefficient linear model.'),
C('Hole, liquid & density',[r'\beta_{\rm app}=\beta_\ell-\beta_{\rm vessel}',r'V_{\rm spill}\simeq V_0\beta_{\rm app}\Delta T',r'\rho(T)\simeq\rho_0(1-\beta_V\Delta T)'],'Imagine filling a hole with the same material: its dimensions expand exactly as the surrounding plate does. For a liquid in a vessel, subtract container expansion to find the apparent increase.','Buoyancy depends on fluid density AND displaced volume. Heating can change both, so follow the complete geometry and mass balance.','A negative apparent coefficient can make the level fall even while the liquid expands. Do not treat the vessel as automatically rigid.'),
C('Blocked expansion creates stress',[r'|\sigma|=Y\alpha|\Delta T|,\quad F=A|\sigma|'],'A fully clamped rod has its free thermal strain cancelled by the supports. Heating creates compression; cooling creates tension. A free rod expands without thermal stress. Steel with Y=200 GPa and alpha=12 micro/K develops 24 MPa for a blocked 10 K rise.','Elastic strain compensates thermal strain; the stress result follows from Hooke\'s law and the zero-total-strain constraint.','Assume small strain and linear elasticity. Yielding, buckling, loose supports or moving supports require a different balance.'),
C('Clock, fit & bimetal',[r'\frac{\Delta\tau}{\tau}\simeq\frac12\alpha\Delta T'],'Heating a simple pendulum increases its period, so the clock loses about alpha delta T/2 seconds per elapsed second. On heating a bimetal the higher-alpha layer becomes the longer OUTER arc. Tyre ID 0.998 m reaching 0.999 m at alpha=12 micro/K needs a RISE about 83.5 K.','Period scales as square root of length. Bonded layers cannot expand independently, so unequal natural strains produce curvature.','Cooling reverses bimetal curvature. A temperature rise is not the final temperature; add the initial temperature separately.'))
J('calorimetry','Calorimetry & phase changes','Draw an energy ledger and decide the final phase before solving for a temperature.','Source §3.3; heating curve and §8 toolkit',['heating','mixing'],'During a phase plateau, energy changes phase, not temperature. Include every stage and the vessel.',
C('Heat capacities and sensible heat',[r'Q=mc\Delta T=C\Delta T',r'Q=m\int_{T_1}^{T_2}c(T)\,dT'],'c is specific heat in J/(kg K), C is total capacity in J/K. A molar capacity must be multiplied by moles, not mass. Constant c is an approximation over a range with little capacity variation and no phase transition.','Capacity describes energy required per temperature change under specified constraints. It is not the amount of heat stored inside a body.','For gases the path matters: fixed-pressure and fixed-volume heating use different capacities. Identify the process before substituting.'),
C('Latent heat and heating plateaus',[r'Q=mL\quad\mathrm{(phase\ change)}'],'At specified pressure a pure substance can melt or boil at constant T. For ice below 0 C: warm ice, melt it, warm water, boil it, then warm steam if energy remains. Water near 1 atm: c=4.18 kJ/(kg K), Lf=334 kJ/kg, Lv=2256 kJ/kg.','Flat temperature on a heating curve does not mean zero energy transfer; energy changes the phase fraction instead.','Transition temperatures and latent heats depend on pressure. Do not silently apply one-atmosphere values under every constraint.'),
C('Insulated mixing: include vessel',[r'\sum_iQ_i+Q_{\rm vessel}=0',r'T_f=\frac{\sum_iC_iT_i}{\sum_iC_i}'],'For insulated mixing with constant capacities, no reaction or phase change and negligible work. Include the vessel at its own initial T. All components share final Tf.','Energy lost by all initially hot components equals that gained by colder components and the container. Internal heat exchanges cancel in the composite.','An unweighted average works only for equal total capacities. Heat loss to the room breaks the isolated energy balance.'),
C('Ice and steam decision tree',[r'Q_{\rm melt}=m_iL_f'],'Compare heat available on cooling warm contents to 0 C with heat required to warm and melt the ice. Insufficient heat leaves residual ice at 0 C; excess heat warms the combined liquid. 0.10 kg ice at 0 C plus 0.20 kg water at 40 C gives nearly the melting threshold.','The final phase selects the correct energy equation. First test the boundary state, then distribute the remaining energy.','Steam releases condensation latent heat before its condensed water cools. Count both; do not use one specific-heat equation through a phase change.'))
J('kinetic-pressure','Ideal gas: pressure from impacts','Dilute equilibrium gas; molecular interactions neglected except for short elastic collisions.','Source §§2.1-2.3; kinetic derivation and example 2.1',['collision','pressure-density'],'At equal T, species have equal mean translational energy per particle, not equal speed.',
C('Momentum arriving at a wall',[r'P=\frac{Nm\langle v_x^2\rangle}{V}',r'P=\frac13\frac{Nm}{V}\langle v^2\rangle'],'In a cube of side L, a molecule transfers 2m|vx| per elastic hit on an x wall. It returns to that wall after 2L/|vx|. Sum its average force over molecules and divide by the wall area.','Isotropy gives equal mean squared velocity components, each one-third of the total. This is the source of the factor 1/3.','The average velocity is zero in a resting gas but the mean squared velocity is positive. m here is ONE molecule\'s mass.'),
C('Energy-temperature bridge',[r'P=\frac13\rho v_{\rm rms}^2',r'\frac12m\langle v^2\rangle=\frac32k_BT',r'K_{\rm trans}=\frac32nRT'],'Combine the momentum-pressure derivation with PV=NkB T. Translational mean kinetic energy depends only on T for any ideal species.','At the same T a heavier molecule moves more slowly. Increased momentum per impact compensates reduced wall arrival frequency.','Rotation and vibration can add internal energy without changing this translational pressure expression. Do not equate total U to translational energy for every gas.'),
C('Density and partial pressure',[r'\rho=\frac{PM}{RT},\quad\nu=\frac{P}{k_BT}',r'P=\sum_iP_i,\quad P_i=\frac{n_iRT}{V}'],'Dalton\'s law applies to a nonreacting ideal mixture at common T and V. Each species contributes its own wall momentum flux. Equal partial pressures at equal T mean equal number densities, not equal masses.','The pressure contributions add because the wall receives independent momentum transfers from all species.','Thermal equilibrium fixes T, not species concentrations. Helium need not have higher wall-arrival flux than argon if helium is sufficiently dilute.'),
C('Useful scales and SI checks',[r'v_{\rm rms}=\sqrt{\frac{3RT}{M}}',r'1\ \mathrm{kPa\,L}=1\ \mathrm J'],'For N2 at 300 K, M=0.028 kg/mol gives rms speed about 517 m/s. kB T per particle is about 4.14 times 10^(-21) J, or 0.0259 eV. At fixed density P scales with T; at fixed T it scales with density.','Temperature links microscopic motion to a directly measurable macroscopic pressure. Unit conversion is part of the physical check.','Large random molecular speed does not imply a large bulk wind. With Pa in PV=nRT, volume must be in cubic metres.'))
J('speeds-collisions','Speeds, collisions & effusion','Maxwell equilibrium gas; hard-sphere diameter d treated as constant.','Source §§2.3-2.6; Q8, Q12, Q20, Q26; flux factor repaired',['maxwell','mfp'],'State what is fixed before scaling lambda. Wall arrivals weight faster molecules more heavily.',
C('Mode, mean and rms',[r'v_p=\sqrt{2RT/M}',r'\bar v=\sqrt{8RT/(\pi M)}',r'v_{\rm rms}=\sqrt{3RT/M}'],'Mode < mean < rms. All scale as square root of T/M. Higher T shifts and broadens the speed distribution; its probability area stays one. For N2 at 300 K the values are about 422, 476 and 517 m/s.','Squaring before averaging emphasises the fast tail. The mean of v squared differs from the square of the mean speed.','The most probable speed is not a component\'s most probable velocity. A resting gas has zero mean vector velocity.'),
C('Mean free path',[r'\lambda=\frac{1}{\sqrt2\pi d^2\nu}',r'\lambda=\frac{k_BT}{\sqrt2\pi d^2P}'],'Collision cross-section is pi d squared, not pi(d/2) squared. The square-root-two factor accounts for relative motion of identical Maxwellian targets. At fixed P, lambda grows with T; at fixed number density it does not depend on T in this model.','A hotter fixed-pressure gas is less dense, so the typical distance between collisions increases even though individual molecules move faster.','The relative-speed factor is an averaged result, not a literal right angle between every pair. Temperature-dependent collision cross-sections require a refined model.'),
C('Collision rate and vacuum scale',[r'z=\bar v/\lambda,\quad\tau_c=\lambda/\bar v'],'For fixed amount and volume, quadrupling T doubles speed and collision frequency but leaves lambda unchanged. With d=3.7 angstrom at 273 K and 1 atm, lambda is about 61 nm and z about 7.4 billion/s. At 10 Pa, lambda is about 0.62 mm, not metres.','Continuum transport requires lambda much smaller than apparatus size. A sufficiently tiny opening enters an effusive rather than hydrodynamic regime.','Molecular collision frequency and acoustic frequency describe different processes. Do not infer one directly from the other.'),
C('Wall flux and Graham ratio',[r'\Gamma=\frac14\nu\bar v',r'\frac1{4\pi}\int_{\rm hemi}\cos\theta\,d\Omega=\frac14',r'r_1/r_2=\sqrt{M_2/M_1}'],'Gamma counts arrivals per unit area per second. For an effusive hole, the initial escape rate is A Gamma. Graham\'s ratio needs equal upstream T and pressure, equal hole geometry and negligible return flux.','The angular projection over the incoming hemisphere supplies the quarter factor, not an arbitrary average of cosine.','For unequal species number densities multiply by the density ratio. A large hole or substantial downstream gas invalidates simple effusion.'))
J('heat-capacities','Degrees of freedom & mixtures','CV and CP are molar unless labelled total or specific. Identify the active-mode regime.','Source §§4.1-4.2, 7.1; molecular classifications corrected',['dof','mixture-capacity'],'Add extensive capacities first; never average gamma directly.',
C('Equipartition and Mayer relation',[r'U=n\frac f2RT,\quad C_V=\frac f2R',r'C_P-C_V=R,\quad\gamma=1+2/f'],'Each active quadratic energy term contributes kB T/2 per particle. A classical vibrational mode has TWO terms, kinetic and potential. At fixed pressure heat must supply both increased U and expansion work.','Per mole the extra isobaric work is R delta T, giving CP=CV+R for an ideal gas.','Constant f requires a suitable temperature range. U may have an arbitrary consistent zero; its change is what enters the first law.'),
C('Molecule shape is not mode count',[r'C_{V,\rm vib\ active\ diatomic}=7R/2'],'Monatomic: f=3, gamma=5/3. Rigid linear molecule: three translations plus two rotations, f=5, gamma=7/5. Rigid nonlinear: three translations plus three rotations, f=6, gamma=4/3. CO2 is LINEAR; CH4 is nonlinear and pentatomic.','Vibration adds two quadratic terms per active mode. It is often frozen in a room-temperature rigid-diatomic approximation.','Diatomic does not mean gamma=7/5 at every T. Nonlinear and triatomic are not synonyms; specify shape and active modes.'),
C('Mixture: add before taking ratios',[r'C_{V,\rm tot}=\sum_i n_iC_{V,i}',r'\gamma_{\rm mix}=1+\frac{n_{\rm tot}R}{\sum_i n_iC_{V,i}}',r'M_{\rm mix}=\frac{\sum_i n_iM_i}{n_{\rm tot}}'],'One mole Ar plus one mole rigid O2 gives total CV=4R, total CP=6R and gamma=1.50. Component energies add at their common T.','A ratio such as gamma must be formed after adding extensive heat capacities, not averaged independently.','Mole fractions and mass fractions are different weights. Convert consistently when a composition is specified by mass.'),
C('When capacities depend on T',[r'\Delta U=n\int_{T_1}^{T_2}C_V(T)\,dT',r'\Delta H=n\int_{T_1}^{T_2}C_P(T)\,dT'],'Use the supplied capacity functions if modes activate over the temperature interval. For ideal gas H=U+PV; with constant capacities delta H=nCP delta T. Enthalpy is a state quantity, whereas heat depends on the path.','Capacity measures how stored energy changes per kelvin. Temperature dependence changes both energy integrals and adiabatic relations.','Constant-gamma power laws can fail across activation regimes. CP-CV=R is not a universal real-gas identity, and delta H is not always heat.'))
J('first-law','First law: boundary before algebra','Q enters the system; W is work BY the system. Keep this convention throughout.','Source §§3.1-3.5; piston and electrical-room examples',['piston','boundary'],'Use the actual resisting load for boundary work. Electrical input is work, even if it eventually becomes thermal energy.',
C('One sign convention',[r'\Delta U=Q-W_{\rm by}',r'Q>0:\ \mathrm{in},\quad W_{\rm by}>0:\ \mathrm{out}'],'This form is for a stationary closed system with negligible changes of bulk kinetic and gravitational energy. Include those changes when the system accelerates or rises. Energy entering increases stored energy; energy leaving decreases it.','U is a state function. Heat and work describe boundary transfers and are path-dependent, not stored properties.','A negative Q means heat leaves. If another convention uses work ON the gas, change signs explicitly before combining equations.'),
C('Boundary work follows resistance',[r'\delta W_{\rm by}=P_{\rm ext}\,dV',r'W_{\rm by}=\int_{V_1}^{V_2}P_{\rm ext}\,dV'],'For a quasistatic frictionless piston in the reversible limit, gas pressure matches external resisting pressure and can replace it in the work integral. Expansion gives positive work; compression gives negative work.','Force times piston displacement is Pext A dx=Pext dV. Pressure alone without displacement does no boundary work.','During a sudden jump, intermediate uniform gas pressures may not exist. Do not integrate a fictional equilibrium gas curve.'),
C('State energy from endpoints',[r'\Delta U_{\rm ideal}=nC_V(T_2-T_1)',r'\Delta U=\frac{C_V}{R}(P_2V_2-P_1V_1)'],'For fixed amount and constant CV, ideal-gas energy change depends only on final and initial temperature or PV values. These endpoint expressions do not require reversibility. Every cycle returns U to its initial value.','Two paths with the same endpoints have the same delta U but can transfer different Q and W.','Ideal-gas isothermal means delta U=0; a real interacting substance may have an isothermal energy change. Do not generalise the ideal result blindly.'),
C('Open fridge in a sealed room',[r'\Delta U=W_{\rm electrical,in}=\mathcal P t'],'Take the whole rigid insulated room including the refrigerator. Cooling and rejected heat are internal transfers; the cord brings electrical work in. 150 W for 2400 s adds 360 kJ. Air in 60 cubic metres at 1 atm, 300 K has about 2437 mol; rigid diatomic CV gives a rise about 7.1 K.','The motor\'s input ultimately warms the composite. Opening the door cannot cool the isolated room.','The room volume is 60, not 0.06 cubic metres. External Q remains zero; electrical work is not relabelled as incoming heat.'))
J('basic-processes','Isochores, isobars & path capacity','Fixed amount of ideal gas, constant capacities, boundary work only unless stated otherwise.','Source §§3.2, 4.1-4.2; process summary',['processes','heat-capacity'],'Find delta U from endpoints, W from the constraint, then Q from the first law.',
C('Isochore: volume fixed',[r'W=0,\quad Q=\Delta U=nC_V\Delta T',r'P_2/P_1=T_2/T_1'],'A rigid vessel prevents displacement work. Heating increases temperature, internal energy and pressure; the vertical P-V path has zero area contribution. Constant-volume heat per kelvin is the total capacity nCV.','No boundary displacement means no boundary work, however large the pressure becomes.','A rigid vessel can still receive electrical or stirring work. With such inputs Q alone need not equal delta U; use the full boundary ledger.'),
C('Isobar: pressure fixed',[r'W=P\Delta V=nR\Delta T',r'Q=nC_P\Delta T',r'\Delta U=nC_V\Delta T'],'At fixed pressure, temperature increase expands the gas. Heat both raises U and supplies displacement work. For a fixed amount, V/T is constant.','Adding energy stored to work delivered gives Q=n(CV+R)delta T, deriving Mayer\'s ideal-gas relation.','The pressure used for work must be the equilibrium resisting pressure. Heating by itself does not specify an isobaric process.'),
C('Capacity along an imposed path',[r'C_{\rm path}=\frac{\delta Q}{n\,dT}',r'C_{\rm path}=C_V+\frac{P}{n}\frac{dV}{dT}'],'From delta Q=dU+P dV for a quasistatic ideal gas. Path capacity is not another intrinsic material constant. It can be negative if expansion consumes more work than incoming heat supplies.','The gas may absorb heat and cool simultaneously because its internal energy pays the balance of the work.','At an isotherm dT=0, so finite nonzero heat cannot define finite C(path). A singular path ratio is not a phase transition.'),
C('Same temperature rise, two bills',[r'Q_V=2079\ \mathrm J,\quad W_V=0',r'Q_P=2910\ \mathrm J,\quad W_P=831\ \mathrm J'],'One mole rigid diatomic gas warms from 300 to 400 K. Both routes give delta U=2.5R times 100, about 2079 J. Their volumes or pressures need not end at the same values.','Subtract Q-W in either row: energy stored is the same. The extra fixed-pressure heat leaves as displacement work.','Do not use nCP delta T for arbitrary heating. The subscript encodes a constraint, not just a choice of numerical constant.'))
J('isotherm-adiabat','Isotherms & reversible adiabats','Isothermal fixes T; adiabatic fixes Q=0. Neither word alone guarantees reversibility.','Source §§3.2, 4.3; example 4.1 and Q27',['iso-adiabat','adiabat-laws'],'PV^gamma needs a reversible ideal-gas adiabat with constant gamma, not merely an insulated wall.',
C('Reversible ideal-gas isotherm',[r'\Delta U=0,\quad Q=W',r'W=nRT\ln(V_2/V_1)'],'Integrate P=nRT/V along a quasistatic frictionless isotherm. A reservoir supplies heat during expansion, preventing cooling; compression rejects an equal amount of heat to keep T fixed.','Work is the area under a decreasing hyperbola, not a fixed-pressure rectangle. The logarithm gives the correct volume-ratio dependence.','An irreversible ideal-gas isotherm still has Q=W but not necessarily logarithmic work. Use the actual external load.'),
C('Derive the adiabatic powers',[r'nC_VdT=-P\,dV',r'\frac{dT}{T}=-\frac{R}{C_V}\frac{dV}{V}',r'TV^{\gamma-1}=\mathrm{constant}',r'PV^\gamma=\mathrm{constant}'],'No heat enters; expansion work comes entirely from internal energy. Separate variables and integrate using the ideal equation and constant CV.','Expansion cools and compression warms because U supplies or receives the boundary work.','Slow or smooth alone does not prove reversibility. Friction and other dissipative mechanisms must also be absent.'),
C('Pressure form and work',[r'T^\gamma P^{1-\gamma}=\mathrm{constant}',r'T_2/T_1=(P_2/P_1)^{(\gamma-1)/\gamma}',r'W=\frac{P_1V_1-P_2V_2}{\gamma-1}',r'W=nC_V(T_1-T_2)'],'Expansion gives positive W and falling T; compression gives negative W and rising T. The two work expressions agree through PV=nRT.','The pressure-ratio exponent includes division by gamma because pressure and volume both change on the adiabat.','Use (gamma-1)/gamma for a pressure ratio; gamma-1 belongs with an inverse volume ratio.'),
C('Compare from the same start',[r'|dP/dV|_S=\gamma P/V,\quad|dP/dV|_T=P/V'],'The expanding adiabat lies below the isotherm from their common initial state. One mole monatomic gas at 300 K doubling V gives adiabatic T2 about 189 K and W about 1384 J; isothermal W is about 1729 J.','The 345 J difference compares two work outputs. The actual adiabatic internal-energy loss is 1384 J, not 345 J.','Equal final volume is not equal final state: the two endpoints have different pressures and temperatures.'))
J('polytropes','Polytropes: derive once, use often','PV^s=constant. s is a path exponent; n remains amount in moles.','Source §4.4; Q10, Q23; formula-sheet limits corrected',['polytropes','poly-signs'],'Expansion with 1<s<gamma absorbs heat while cooling: work consumes more than incoming heat supplies.',
C('Endpoint relation and work',[r'TV^{s-1}=\mathrm{constant}',r'T_2/T_1=(V_1/V_2)^{s-1}',r'W=\frac{P_2V_2-P_1V_1}{1-s}\quad(s\ne1)',r'W=\frac{nR(T_2-T_1)}{1-s}'],'Integrate K V^(-s) dV on the quasistatic path. The relation between T and V follows by substituting PV=nRT into PV^s=K.','One integration covers many familiar paths and keeps the signs tied to the actual direction of volume change.','For s=1 use logarithmic isothermal work. A polytropic exponent is not automatically gamma.'),
C('Heat capacity on the polytrope',[r'Q=nC_s\Delta T',r'C_s=C_V+\frac{R}{1-s}',r'C_s=C_V\frac{s-\gamma}{s-1}'],'First-law heat equals stored energy plus work. The volume-change contribution may make the path capacity negative. The integrated forms require constant s and effectively constant capacities.','This is a property of the chosen route, not negative intrinsic CV. The same gas can follow different paths with different heat bills.','At s=1, finite heat divided by zero temperature change is undefined; the formal divergence does not describe a phase change.'),
C('Expansion sign map',[r'1<s<\gamma\ \Rightarrow\ C_s<0'],'For expansion: s<1 warms with Q in; s=1 has fixed T and Q in; 1<s<gamma cools with Q in; s=gamma has Q=0; s>gamma cools with Q out.','In the negative-capacity window, expansion work exceeds the heat received; the difference comes from internal energy.','Reversing the same path reverses Q, W and delta T. Judge heat with both the capacity sign and traversal direction, not from slope alone.'),
C('Limits and checked compression',[r'T_2=300\sqrt2=424.3\ \mathrm K',r'C_s=-R/2,\quad Q\simeq-517\ \mathrm J'],'s=0 isobar; s=1 isotherm; s=gamma reversible adiabat; limiting vertical absolute s to infinity is ISOCHORE. Example: one mole monatomic gas at 300 K, s=1.5, compressed to half-volume gives the values above.','The gas warms while rejecting heat: compression work exceeds the internal-energy increase. Check with Q=delta U+W.','The infinite-exponent limit is not an isobar. Avoid the source\'s overloaded use of n for both exponent and moles.'))
J('arbitrary-paths','P-V paths: integrate, then account','Frictionless quasistatic boundary work equals the signed area under P(V).','Source §§3.5, 8.2; supporting spring and local-heat derivations',['linear-path','spring'],'Solve the constraints, integrate W, find endpoint delta U, then recover Q. Heat direction need not follow slope.',
C('Universal route for a known curve',[r'W=\int_{V_1}^{V_2}P(V)\,dV',r'Q=\frac{C_V}{R}\Delta(PV)+W'],'Fixed amount of ideal gas with constant CV. Even if n is unknown, endpoint PV gives the internal-energy difference. The gas equation translates a mechanical plot into temperature information.','The first law supplies heat without memorising a separate formula for each named or unusual path.','A positive-pressure curve gives negative W when traversed right to left. An irreversible jump may not define a uniform gas-pressure curve.'),
C('Straight segment and maximum T',[r'W=\frac{P_1+P_2}{2}(V_2-V_1)',r'P=aV+b\ \Rightarrow\ T=(aV^2+bV)/(nR)',r'\frac{dT}{dV}=\frac{2aV+b}{nR}'],'The signed trapezium area is exact for a straight P-V segment. A temperature extremum occurs at 2aV+b=0 only if the point lies inside the allowed segment.','T depends on the product PV, not P alone. Maximum pressure and maximum temperature can occur at different states.','A stationary point outside the process interval is inaccessible; compare the permitted endpoints instead.'),
C('Heat can change sign within a leg',[r'\frac{\delta Q}{dV}=\frac{C_V}{R}\left(P+V\frac{dP}{dV}\right)+P'],'Substitute the curve and find zeros of this local heat rate. For P=aV+b the bracket is 2aV+b. Split the heat ledger at internal sign reversals before computing engine intake.','A leg\'s net heat can hide intake on one portion and rejection on another. Efficiency counts ALL positive intake, not just positive net leg totals.','The derivative is per increasing V. During compression dV reverses its sign, so inspect traversal direction.'),
C('Linear spring-loaded piston',[r'P=P_0+Mg/A+kx/A',r'V=V_0+Ax',r'W=(P_0A+Mg)x+\frac12kx^2'],'Vertical frictionless piston with constant load and a spring unstrained at x=0. A preload changes the pressure intercept; spring loading gives the linear slope.','Gas work pays atmospheric displacement, lifting the load and spring energy. Including the piston/spring in a larger system changes the boundary ledger.','At a hard stop volume becomes fixed. Do not continue the spring line past its mechanical range.'))
J('irreversible','Insulated is not isentropic','Sudden processes need the actual load and an explicit relaxation/energy-deposition model.','Source §§3.4, 4.3; Q13 and repaired Q27',['free-expansion','compression'],'Q=0 alone does not determine W. Do not paste reversible power laws onto a sudden process.',
C('Insulated free expansion',[r'P_{\rm ext}=0\ \Rightarrow\ W=0',r'Q=0\ \Rightarrow\Delta U=0',r'\Delta T=0\quad\mathrm{(ideal\ gas)}'],'Remove a partition between gas and vacuum inside a rigid insulated enclosure. Intermediate gas states need not have uniform pressure or temperature; only initial and final equilibrium states are used.','No resisting load means no delivered boundary work. Ideal U depends only on T, so final temperature is unchanged.','This is not a reversible isotherm and produces no logarithmic work. Entropy rises despite Q=0.'),
C('Constant external pressure',[r'W=P_{\rm ext}(V_2-V_1)',r'nC_V(T_2-T_1)=Q-P_{\rm ext}(V_2-V_1)'],'Apply final mechanical balance separately. A settled piston matches the total resisting load if no additional uncounted frictional force acts. The initial gas pressure can differ from the imposed external pressure.','Endpoint equilibrium does not make the preceding route reversible. Work follows the surroundings\' actual force through the displacement.','Kinetic energy, stop impacts and friction can send energy outside a gas-only boundary. Specify where transient mechanical energy ends.'),
C('Sudden insulated compression',[r'C_V(T_2-T_1)=RT_2(r-1)',r'\frac{T_2}{T_1}=\frac{1}{1-(\gamma-1)(r-1)}'],'Compress to V2=V1/r using a constant load equal to final P2. Assume all transient mechanical energy thermalises in the gas. Work input is P2(V1-V2); substitute P2V2=nRT2.','The result comes from energy and final force balance, not a reversible adiabatic curve. It defines a particular endpoint model.','The denominator must remain positive. A perfectly undamped frictionless piston does not simply settle: a relaxation mechanism must be specified.'),
C('Same ratio, different final states',[r'\Delta S_{\rm sudden}=nC_V\ln(500/300)-nR\ln2>0'],'Two moles rigid diatomic gas at 300 K compressed to half-volume: reversible isothermal gives T2=300 K, input 3.458 kJ; reversible adiabatic gives 395.9 K and 3.985 kJ; sudden insulated model gives 500 K and 8.314 kJ.','More compression work is stored as internal energy in the sudden case. The processes do not share the same final T or P.','The two-mole sudden work is not 4.16 kJ; that loses a factor of two. Check nCV delta T independently.'))
J('cycle-ledgers','Cycles: count heat, not just area','Every true cycle returns system U and S to their initial values, even if irreversible.','Source §§3.5, 6.1, 8.2-8.4; Q9 and repaired three-leg cycle',['triangle','cycle-ledger'],'Efficiency divides net work by total heat absorbed, never by net heat. Split heat-sign reversals.',
C('Close all state-function columns',[r'\sum\Delta U_i=0,\quad W_{\rm net}=Q_{\rm net}',r'\eta=\frac{W_{\rm net}}{Q_{\rm in}}=1-\frac{Q_{\rm out}}{Q_{\rm in}}'],'Qin and Qout are positive magnitudes. Add every positive heat contribution to Qin and every rejected magnitude to Qout. Net heat alone is not the engine\'s heat intake.','A clockwise equilibrium P-V boundary-work loop has positive enclosed work; reverse traversal gives negative work.','For irreversible jumps the gas-pressure path may be undefined. Do not interpret every schematic loop as actual work.'),
C('A dependable cycle procedure',[r'W_{\rm triangle}=\frac12\Delta P\Delta V'],'Label states, directions, units and constraints. Find temperatures using PV=nRT; calculate W and delta U per leg; use Q=delta U+W. Split local heat reversals, sum the columns, then form efficiency or COP. A clockwise 150 kPa by 6 L triangle gives 450 J.','Column closure and a separate geometric area check expose both sign errors and missed heat contributions.','A triangular loop is half a rectangle. Convert units consistently: 1 kPa litre equals 1 joule.'),
C('A fully specified three-leg cycle',[r'W_{\rm net}=P_0V_0(2\ln2-1)',r'Q_{\rm in}=P_0V_0(C_V/R+2\ln2)'],'A=(P0,V0,T0), B=(2P0,V0,2T0), C=(P0,2V0,2T0). A to B isochoric; B to C reversible isothermal; C to A isobaric. With rigid diatomic CV=5R/2, efficiency is about 9.94%. One mole at T0=300 K gives W about 964 J.','Intake occurs on BOTH the isochore and the isotherm. Count both before forming eta.','Use consistent capacities and baseline states. One atmosphere times 24.9 litres per mole is about 303.5 K, not exactly 300 K.'),
C('P-V area versus T-S area',[r'\delta Q_{\rm rev}=T\,dS',r'Q_{\rm rev,net}=\oint T\,dS'],'For a reversible cycle, the enclosed T-S area equals net heat and hence net work. Reversible isotherms are horizontal, reversible adiabats vertical. Isochoric heat-transfer legs are curved, not flat.','The Carnot rectangle has area (Th-Tc)delta S; its interpretation follows directly from reversible heat transfer.','For an irreversible cycle, system T-S area is not generally actual heat. Quasistatic alone is insufficient; system delta S still sums to zero.'))
J('second-law','Second law & the Carnot ceiling','Fixed reservoirs Th>Tc. Qh and Qc denote positive heat magnitudes; use kelvins.','Source §§5.1-5.3; equivalence proof and Carnot construction',['engine','carnot-ts'],'The first law balances energy; the second law limits direction and the fraction convertible into useful work.',
C('Two equivalent prohibitions',[],'Kelvin-Planck: no cyclic device has as its sole effect extracting heat from one reservoir and turning it all into work. Clausius: no cyclic device has as its sole effect transferring heat from cold to hot without work.','A hypothetical work-free fridge returning an engine\'s rejected Qc to the hot bath makes the composite turn Qh-Qc from one reservoir entirely into work.','SOLE EFFECT and cyclic operation matter. A single reversible isothermal expansion can convert all its absorbed heat into work without violating the statement.'),
C('Carnot: four reversible legs',[r'Q_h=nRT_h\ln(V_2/V_1)',r'Q_c=nRT_c\ln(V_3/V_4)',r'V_2/V_1=V_3/V_4'],'Expand isothermally at Th; expand adiabatically to Tc; compress isothermally at Tc; compress adiabatically to Th. Both adiabats give the same volume scaling between the two temperatures.','The equal volume ratios cancel the logarithms in Qc/Qh, leaving a temperature-only ratio.','This explicit PV derivation uses an ideal gas. The reversible efficiency theorem itself is independent of working substance.'),
C('Entropy gives the bound',[r'\eta\le1-T_c/T_h',r'Q_c/T_c-Q_h/T_h=S_{\rm gen}\ge0'],'The entropy account includes the cyclic engine and both reservoirs. Equality requires no total entropy generation. Friction, mixing, turbulence and finite-temperature heat transfer reduce work for a specified heat intake.','Energy remains conserved while entropy generation lowers the energy\'s availability for work. The efficiency gap is governed by the second law.','Do not describe real-engine losses as energy destruction or claim that none of the efficiency gap involves the second law.'),
C('Meaningful comparisons and limits',[r'T_h=T_c\ \Rightarrow\eta_C=0'],'A reversible 600 K to 300 K engine has 50% efficiency. An 800 K to 400 K engine claiming 50% is at the ceiling, not above it. Unit efficiency requires Tc/Th approaching zero; the reversible model alone does not guarantee finite power.','Heat received across a temperature range gives a lower useful fraction than receiving all heat at the maximum T.','Maximum and minimum gas T provide only a loose bound for a non-Carnot cycle; compare actual reservoir/heat-transfer models.'))
J('refrigerators','Refrigerators, pumps & cascades','The cold-side extraction is useful for a fridge; hot-side delivery is useful for a heat pump.','Source §5.4; Q11, Q33; three-reservoir ledger',['fridge','cascade'],'COP can exceed one because the device moves heat; work is not the only source of delivered heat.',
C('One balance, two objectives',[r'Q_h=Q_c+W_{\rm in}',r'\mathrm{COP}_R=Q_c/W_{\rm in}',r'\mathrm{COP}_H=Q_h/W_{\rm in}',r'\mathrm{COP}_H=\mathrm{COP}_R+1'],'The hot side receives extracted cold-side heat plus input work. The two COPs refer to the SAME machine under the same operating conditions.','The extra one in heat-pump COP is precisely the work input ultimately delivered at the hot side.','Engine efficiency divides work OUT by source heat IN. Do not simply invert a formula without tracing all flows.'),
C('Reversible temperature ceilings',[r'\mathrm{COP}_R\le T_c/(T_h-T_c)',r'\mathrm{COP}_H\le T_h/(T_h-T_c)'],'Equality requires a reversible machine between two reservoirs. Increasing the temperature lift lowers both ideal COPs. Combine Qh/Th=Qc/Tc with the first-law balance to derive the reversible expressions.','A small temperature lift lets the machine move large heat per unit work, consistent with energy conservation.','Real heat exchangers require finite temperature differences. The working-fluid lift may be larger than the quoted room-temperature lift; actual COP is lower.'),
C('Use rates or energies consistently',[r'\mathrm{COP}_R=270/30=9',r'\dot Q_c=1350\ \mathrm W,\quad\dot Q_h=1500\ \mathrm W',r'1500/300=1350/270'],'A reversible fridge holds 270 K while the room is 300 K and motor input is 150 W. Multiply all rates by the same operating time for energies.','The last line checks matching entropy rates in the reversible machine. Heat rejection must exceed extracted heat by motor input.','A watt is joules per second, not joules. Cooling capacity is different from electrical input power.'),
C('Engine drives a heat pump',[r'\Delta S=-\frac{1000}{600}+\frac{500-3000}{300}+\frac{3500}{350}=0'],'Per 1000 J from a 600 K source, a reversible engine rejecting to 300 K makes 500 J work. Drive a reversible pump from 300 to 350 K: COP(H)=7, delivery 3500 J, extraction 3000 J.','There are THREE physical reservoirs. The outside 300 K account combines engine rejection and pump extraction, giving net 2500 J removed.','Heat delivery exceeds source heat because more heat came from outside, not because the cascade creates energy.'))
J('standard-cycles','Otto, Diesel & regeneration','Ideal-gas cycle applications: derive from the legs and state heat-storage assumptions.','Source §4.6, Q29; supporting regenerative-cycle comparison',['otto','stirling'],'Otto has two adiabats and two isochores, with no horizontal isothermal heat-transfer leg on T-S.',
C('Otto efficiency in a few steps',[r'T_2/T_1=T_3/T_4=r^{\gamma-1}',r'\eta=1-\frac{T_4-T_1}{T_3-T_2}',r'\eta_O=1-r^{1-\gamma}'],'Compression and expansion are reversible adiabatic. Heat addition and rejection are at fixed volume. Define compression ratio r=V1/V2>1 and assume constant capacities.','Both heats use nCV, which cancels. Adiabatic ratios eliminate the four endpoint temperatures.','The air-standard model is idealised heat addition, not a combustion-chemistry calculation. Real engine restrictions are additional.'),
C('Otto numerical temperature map',[r'T_2\simeq689\ \mathrm K,\quad T_3\simeq1378\ \mathrm K',r'T_4=600\ \mathrm K,\quad\eta\simeq56.5\%'],'Rigid diatomic gas, gamma=1.4, r=8, T1=300 K; constant-volume intake doubles T2. Carnot using 1378 K and 300 K gives about 78.2%, a ceiling rather than Otto efficiency.','Intake occurs across 689 to 1378 K, not wholly at the highest T. The curved T-S intake gives less area than its bounding rectangle.','Raising ideal r also raises temperatures. Material strength, combustion and temperature-dependent capacities limit extrapolation.'),
C('Diesel: fixed-pressure intake',[r'\eta_D=1-\frac{q^\gamma-1}{\gamma(q-1)r^{\gamma-1}}'],'Replace Otto\'s isochoric intake by isobaric heating. Define r=V1/V2 and cutoff q=V3/V2 with 1<q<r. Use Qin=nCP(T3-T2), Qout=nCV(T4-T1), then the adiabatic relations.','The extra factor accounts for the finite intake stroke. As q approaches one, the formula approaches the Otto limit.','Choose CP or CV from the actual heat-transfer leg. Equal-r ideal formulas alone do not rank real petrol and diesel engine technologies.'),
C('Stirling and perfect regeneration',[r'W=nR(T_h-T_c)\ln r',r'Q_{h,\rm ext}=nRT_h\ln r',r'\eta=1-T_c/T_h\quad\mathrm{(perfect\ regeneration)}'],'Two isotherms at Th and Tc are joined by two isochores. A perfect regenerator stores isochoric cooling heat and returns it during isochoric heating.','Without regeneration, external source intake additionally includes nCV(Th-Tc), reducing efficiency. The Ericsson analogue uses isobars with ideal regeneration.','Separate externally supplied heat from internally recovered heat. The regenerative assumption is essential to Carnot equality.'))
J('entropy','Entropy: state change & generation','Absolute temperature throughout. Specify the system and temperature at each heat-exchange boundary.','Source §§6.1-6.3; Q13-Q18, Q25; irreversible-area caveat',['entropy-path','entropy-free'],'Use a reversible comparison route to compute delta S even when the actual process is irreversible.',
C('Definition and entropy balance',[r'dS=\delta Q_{\rm rev}/T',r'\Delta S_{\rm sys}=\int\frac{\delta Q}{T_b}+S_{\rm gen}',r'S_{\rm gen}\ge0'],'Tb is the temperature where heat crosses the system boundary. Sum transfers over multiple regions or reservoirs as needed. Entropy can be transferred with heat and generated by irreversibility.','A closed system\'s entropy may decrease if enough entropy leaves. The isolated composite\'s entropy cannot decrease.','Adiabatic reversible means isentropic; adiabatic irreversible generally produces entropy. Do not replace actual heat by reversible heat without stating the comparison route.'),
C('Ideal-gas endpoint formulas',[r'\Delta S=nC_V\ln(T_2/T_1)+nR\ln(V_2/V_1)',r'\Delta S=nC_P\ln(T_2/T_1)-nR\ln(P_2/P_1)'],'Fixed amount and constant capacities. Derive with a reversible isochore followed by an isotherm, or use T dS=dU+P dV with the ideal equation of state.','Entropy difference depends only on endpoints. The real route need not match the reversible route used to evaluate it.','For capacity varying with T, replace C ln(T2/T1) by the integral of C(T)/T. All logarithm arguments must be dimensionless ratios.'),
C('Reservoir, finite body and phase',[r'\Delta S_{\rm bath}=-Q_{\rm into\ system}/T_{\rm bath}',r'\Delta S_{\rm body}=C\ln(T_2/T_1)',r'\Delta S_{\rm phase}=mL/T_{\rm transition}'],'A reservoir stays at fixed T; a finite body changes T and needs integration. The phase expression uses reversible latent heat at equilibrium transition temperature.','Cooling decreases a body\'s entropy but can increase total entropy once the receiving environment is included.','Do not use an arbitrary mean T for a changing body, or assign the gas\'s T to a different reservoir\'s entropy account.'),
C('Free expansion and closed cycles',[r'\Delta S_{\rm free}=nR\ln(V_2/V_1)>0',r'\Delta S_{\rm system,cycle}=0',r'\oint\delta Q/T_b\le0'],'Ideal insulated free expansion has Q=W=0 but positive delta S. A hypothetical reversible isotherm calculates that same endpoint difference. Every true cycle, reversible or not, returns system S to its original value.','For an irreversible cycle, positive generation must be exported to the surroundings to close system entropy.','A nonzero sum of system entropy changes around a claimed cycle indicates a state or ledger error, not merely irreversibility.'))
J('entropy-applications','Finite sources: energy plus entropy','Useful Advanced applications stay with the core laws; specialised availability follows in Part II.','Source §§6.3, 8.4; Q7, Q30; small-gap factor repaired',['reservoirs','finite-engine'],'Direct contact and reversible work extraction reach different final states: arithmetic versus geometric means.',
C('Heat down a temperature gradient',[r'\Delta S_{\rm total}=Q(1/T_c-1/T_h)>0'],'Transfer 1200 J directly from a 400 K reservoir to a 300 K reservoir: hot entropy change -3 J/K, cold +4 J/K, total +1 J/K. Energy balances but entropy is produced.','The same heat carries a larger entropy increment at the colder destination. Thermal energy becomes less available for work.','A fixed reservoir formula needs a genuinely fixed temperature. Finite bodies must be integrated as their temperatures change.'),
C('Mixing finite bodies',[r'T_f=\frac{C_1T_1+C_2T_2}{C_1+C_2}',r'S_{\rm gen}=C_1\ln(T_f/T_1)+C_2\ln(T_f/T_2)',r'S_{\rm gen}\simeq C\delta^2/(4\bar T^2)'],'Insulated direct contact, constant capacities and no external work. Last line: equal capacity C for EACH body, initial temperatures Tbar plus/minus delta/2. Two one-kg water samples at 80 and 20 C generate about 36 J/K for the pair.','The first-order entropy terms cancel, leaving a second-order small-gap result.','Delta is the FULL temperature gap; C is not the combined capacity. Define both before comparing coefficients.'),
C('Reversible engine between bodies',[r'C_1\ln(T_f/T_h)+C_2\ln(T_f/T_c)=0',r'T_f=(T_h^{C_1}T_c^{C_2})^{1/(C_1+C_2)}',r'W_{\max}=C_1(T_h-T_f)+C_2(T_c-T_f)'],'Operate infinitesimal reversible engine stages until the bodies meet at Tf. The composite is adiabatic and has no entropy generation. For equal capacities Tf is the geometric mean.','It is below the arithmetic mean because some stored energy leaves as work instead of remaining in the bodies.','This is not the final state of direct contact. Compare work only after specifying the same process objective and boundaries.'),
C('Finite hot source, infinite sink',[r'dW=(1-T_0/T)(-C\,dT)',r'W_{\max}=C[(T_h-T_0)-T_0\ln(T_h/T_0)]'],'Cool a body reversibly to fixed ambient T0. Integrate the changing Carnot efficiency rather than using its initial value for all heat. Equal one-kg water bodies at 373.15 and 293.15 K yield about 20.2 kJ together; the hot body against a fixed 293.15 K bath yields about 38.8 kJ.','The useful fraction falls as the source cools, reaching zero at T0. A finite sink warms, changing the result.','An infinite sink and a finite cold body are different resources; their maximum-work values need not agree.'))
J('heat-transfer','Heat transfer: rates & resistance','Companion thermal physics: combine rate laws with steady or transient energy balances.','Source §§7.5-7.6, §8 toolkit; supporting Fourier networks',['conduction','radiation'],'Steady state equates rates in and out. Their difference during a transient changes stored energy.',
C('Fourier conduction',[r'\dot Q=-kA\,dT/dx',r'\dot Q=kA(T_h-T_c)/L',r'R_{\rm th}=L/(kA),\quad\dot Q=\Delta T/R_{\rm th}'],'The second expression assumes a uniform rod, constant conductivity, steady one-dimensional flow and no side loss. Thermal conductivity k has units W/(m K), distinct from kB.','Every steady slice transmits the same heat per second. Constant k and area then produce a linear temperature profile.','Varying area, k(T), contact resistance and side loss require extra terms or integration; one L/(kA) may be insufficient.'),
C('Series, parallel and junction T',[r'R_{\rm series}=\sum_iR_i',r'1/R_{\rm parallel}=\sum_i1/R_i',r'T_j=T_h-\dot Q R_{h\to j}'],'Series layers carry the same heat rate; temperature drops divide in proportion to resistance. Parallel paths share end temperatures; their heat rates add. Find unknown junction T from the common heat rate.','Energy continuity, not an unweighted temperature average, determines an interface temperature. Contact resistance adds its own drop.','Side leakage invalidates a simple constant-rate series chain. Check each resistance\'s geometry and area before adding it.'),
C('Radiation and spectral peak',[r'\mathcal P_{\rm net}=\epsilon\sigma A(T^4-T_0^4)',r'\lambda_{\max}T=b_W'],'Grey body in a large uniform enclosure; epsilon=1 for a black body. sigma about 5.67 times 10^(-8) W/(m² K^4); Wien bW about 2.898 times 10^(-3) m K.','Net radiation vanishes at equal T and reverses for a colder body. Kirchhoff\'s emission/absorption relation needs the proper equilibrium spectral comparison.','Use kelvins in fourth powers. Wien\'s peak is per wavelength interval, not a spectral-line relation or the frequency-density peak.'),
C('Multiple mechanisms and equilibrium',[r'C\,dT/dt=\mathcal P_{\rm in}-\mathcal P_{\rm out}',r'T_{\rm eq}=\left[\frac{S_\odot(1-\mathcal A)}{4\epsilon\sigma}\right]^{1/4}'],'Add conduction, convection and radiation as the model requires. Steady state sets net power to zero. A uniformly warm planet intercepts sunlight on pi R² but emits over four pi R²; calligraphic A denotes albedo.','The factor four is an area ratio, not an engine efficiency or loss factor.','Greenhouse effects and nonuniform temperature require a richer model. Effective radiating T is not automatically surface T.'))
J('cooling','Cooling laws & time scales','Lumped body with approximately uniform internal temperature; ambient T0 held fixed.','Source §7.6; Q5 instantaneous versus average-rate correction',['cooling','cooling-log'],'Equal time intervals remove equal fractions of temperature excess, not equal temperature drops.',
C('Newton cooling from energy balance',[r'C\,dT/dt=-hA(T-T_0)',r'T-T_0=(T_i-T_0)e^{-t/\tau}',r'\tau=C/(hA)'],'h is an effective surface heat-transfer coefficient. A constant exponential needs nearly constant h, capacity, area and ambient T. The body cools fastest initially, then slows as temperature excess decreases.','Separating d(T-T0)/(T-T0)=-dt/tau gives the exponential directly, not a constant kelvins-per-minute law.','A body with strong internal gradients needs a conduction model instead of a single lumped T. Changing airflow can change h.'),
C('Subtract ambient before logarithms',[r'\frac{T(t+\Delta t)-T_0}{T(t)-T_0}=e^{-\Delta t/\tau}',r't_{1\to2}=\tau\ln\frac{T_1-T_0}{T_2-T_0}'],'In a 20 C room, cooling 80 to 60 C takes tau ln(3/2); cooling 60 to 40 C takes tau ln2. Equal absolute drops therefore take unequal times.','Equal times reduce remaining excess by a fixed factor. The log-excess plot is linear under the constant-coefficient model.','Temperature differences may use K or Celsius, but bath T must be subtracted before taking their ratio.'),
C('Radiation close to equilibrium',[r'T^4-T_0^4\simeq4T_0^3(T-T_0)',r'h_{\rm rad}=4\epsilon\sigma T_0^3',r'\tau\simeq\frac{C}{A(h+4\epsilon\sigma T_0^3)}'],'For excess much smaller than absolute T0, linearise radiation. Convection and linearised radiation act as parallel heat-loss mechanisms; their coefficients add.','Far from ambient the fourth-power law is strongly nonlinear and one fixed exponential can become inaccurate.','Use absolute T0 in the coefficient even if excess is written in Celsius. Do not extrapolate this near-equilibrium approximation to a glowing hot body.'),
C('A derivative is not an average',[r'|\dot T|_T=(T-T_0)/\tau',r'|\dot T|_{60}/|\dot T|_{80}=(60-20)/(80-20)=2/3'],'The ratio compares instantaneous rates at 60 and 80 C in a 20 C room. The first-minute average is [Ti-T(60 seconds)]/60 seconds, not exactly the initial derivative.','A short interval relative to tau can justify approximating an average by an instantaneous rate, but the approximation must be stated.','Do not combine an exact exponential model with an unstated constant-rate shortcut. Keep time units consistent when extracting tau.'))
J('thermal-mechanics','Thermal mechanics: close the constraints','Piston loads, gas oscillations, sound and buoyancy require both mechanical and thermal models.','Source §§3.2, 4.5, 7.3; gas-spring and balloon corrections',['gas-spring','balloon'],'A force constraint and an energy constraint are both needed. Neither replaces the other.',
C('Piston loading and friction',[r'P_{\rm gas}A=P_0A+Mg+kx'],'For quasistatic frictionless motion balance atmosphere, weight, spring and any other forces. Dry friction adds resistance for upward motion and reverses direction for downward motion. Static friction can permit an interval of resting pressures.','Mechanical equilibrium need not mean equal pressures across a loaded piston. Thermal equilibrium does not remove external forces.','At a hard stop V is fixed even if heating continues. During acceleration include piston inertia and any kinetic-energy storage.'),
C('Small gas-spring stiffness',[r'\delta P=-\kappa(P/V)\delta V',r'k_g=\kappa PA^2/V',r'\omega=\sqrt{(k+k_g)/M_{\rm eff}}'],'A single chamber drives a piston with delta V=A delta x. Kappa=1 for an isothermal response, gamma for reversible adiabatic response. Two chambers contribute additive restoring stiffnesses.','Compression increases pressure and generates a restoring force. The relation of mechanical and thermal time scales selects the appropriate model.','For air, isothermal stiffness is 1/1.4 of adiabatic, about 29% lower, not 8%. Equilibrium pressure must include the load.'),
C('Sound: an adiabatic bulk modulus',[r'B_S=-V(\partial P/\partial V)_S=\gamma P',r'c_s=\sqrt{\gamma P/\rho}=\sqrt{\gamma RT/M}'],'Small nearly reversible compressions and rarefactions exchange little heat over one acoustic period in the usual regime. A pressure wave travels without transporting the whole gas at that speed.','An isothermal model predicts sqrt(P/rho), too small by sqrt(gamma). Molecular thermal motion sets the speed scale.','Composition, heat-capacity relaxation and the thermal regime matter. Do not impose one fixed gamma for every medium or frequency.'),
C('Open hot-air balloon',[r'\rho=PM/(RT)',r'm_{\rm payload}=V(\rho_{\rm out}-\rho_{\rm in})-m_{\rm shell}'],'The open bottom approximately equalises inside/outside pressure. Heating reduces inside density. Displaced outside air supplies buoyancy; subtract enclosed air and fixed structure/basket masses. At altitude recompute pressure and both temperatures.','The useful lift is a density DIFFERENCE, not just displaced-air weight. Different gas compositions require their own molar masses.','Open means matter can leave. Heating at fixed P and V cannot also preserve the same amount of ideal gas.'))
O('statistics','Microstates & quantum mode activation','Specialised counting and temperature-dependent storage beyond fixed-f ideal-gas models.','Source §§6.4, 7.1; supporting partition-function tool',['counting','mode-capacity'],'Equipartition is an active-mode classical limit. Counting and distinguishability are part of the model.',
C('Entropy counts compatible states',[r'S=k_B\ln\Omega',r'\Omega_2/\Omega_1=e^{\Delta S/k_B}'],'Omega counts microstates compatible with a specified macrostate and statistical model. N independent left/right choices have two-to-the-N assignments. All-left has one assignment; near-half macrostates have enormous multiplicity.','Large entropy changes represent exponentially large multiplicity ratios, explaining overwhelming macroscopic directionality without imposing a microscopic one-way trajectory.','Macrostate probability includes multiplicity. Do not confuse one microstate with an entire macrostate or assert a universal recurrence timescale from counting alone.'),
C('Mixing distinct ideal gases',[r'\Delta S_{\rm mix}=-R\sum_i n_i\ln x_i',r'x_i=n_i/n_{\rm tot}'],'Initially separated distinct ideal gases at equal T and P mix into their combined volume. Calculate each species\' accessible-volume increase. At fixed total moles, binary mixing entropy is greatest at equal mole fractions.','Every distinct species gains accessible volume; adding its ideal expansion entropy produces the composition formula.','Identical samples at equal T and P gain no thermodynamic mixing entropy when the partition is removed. Do not silently change distinguishability or hide other state changes.'),
C('Quantum freezing of modes',[r'k_BT\ll\Delta E:\ \mathrm{excitation\ suppressed}',r'C_{V,\rm vib}=R\frac{x^2e^x}{(e^x-1)^2},\quad x=\Theta_v/T'],'One harmonic vibrational mode contributes CV approaching zero at low T and R at high T, counting both kinetic and potential energy terms. Rotations often activate before vibrations because their energy gaps are smaller.','Discrete levels suppress excitation when thermal energy is too small. Smooth population changes create capacity steps rather than a universal fixed integer f.','Anharmonicity, dissociation and nuclear-spin effects require more detailed models. Classical equipartition cannot be applied to frozen modes.'),
C('Partition function as a tool',[r'Z_1=\sum_jg_je^{-\beta E_j},\quad\beta=1/(k_BT)',r'\langle E\rangle=-\partial\ln Z_1/\partial\beta',r'C_V=(\partial U/\partial T)_V'],'gj is level degeneracy. Independent factorised degrees of freedom give additive mean energies. Differentiate the mean energy with respect to T to calculate capacity rather than guessing mode counts.','The partition sum weights excitation populations and links a microscopic spectrum to observable energy storage.','Particle indistinguishability and quantum statistics require additional counting factors. A one-particle expression is not by itself a universal many-body partition function.'))
O('effusive-beams','Effusive beams & thermal escape','The wall samples flux-weighted speeds, not an unweighted random molecule from the vessel.','Source §§2.6, 7.2; Q28 and corrected Q34 escape exponent',['beam','escape-tail'],'An effusive beam is enriched in fast molecules. Retention needs a model and timescale, not rms speed alone.',
C('Equilibrium speed density',[r'f(v)=4\pi\left(\frac{m}{2\pi k_BT}\right)^{3/2}v^2e^{-mv^2/(2k_BT)}',r'\int_0^\infty f(v)\,dv=1'],'The Maxwell distribution is a probability density per unit SPEED in a dilute classical equilibrium gas. A Cartesian velocity component has a different distribution.','The v-squared shell factor competes with the falling Boltzmann exponential to give a nonzero speed peak.','Most probable component velocity is zero even though most probable speed is not. State the normalisation and variable before taking moments.'),
C('Flux selects faster particles',[r'f_{\rm beam}(v)\propto vf(v)\propto v^3e^{-av^2}',r'a=m/(2k_BT)',r'v_{p,\rm beam}=\sqrt{3k_BT/m}',r'\langle E\rangle_{\rm beam}=2k_BT'],'A faster particle reaches the aperture more often. Differentiate the weighted distribution to obtain its peak, and integrate its energy to obtain the mean.','Bulk mean translational energy is 3kB T/2; speed weighting raises the beam mean to 2kB T.','Hole size must be much smaller than lambda and return flux negligible. A hydrodynamic jet is not an effusive beam.'),
C('Insulated effusive vessel cools',[r'U=\frac32Nk_BT,\quad dU=2k_BT\,dN',r'dT/T=\frac13dN/N',r'T/T_i=(N/N_i)^{1/3}'],'Rigid insulated monatomic vessel, leaking slowly enough to maintain internal Maxwell equilibrium. Both dN and dT are negative. Escaping particles remove their flux-weighted mean energy.','Each escaping molecule carries more energy than the mean molecule remaining in the vessel, so the remainder cools.','This is an OPEN mass-losing system. It is not closed insulated free expansion, where ideal gas has no temperature change.'),
C('Jeans escape: qualify the tail',[r'\Lambda=\frac{mv_{\rm esc}^2}{2k_BT}=\frac{3v_{\rm esc}^2}{2v_{\rm rms}^2}',r'\Gamma_J=\frac{\nu\bar v}{4}(1+\Lambda)e^{-\Lambda}'],'Maxwellian exobase, collisionless outward escape above the binding energy. Exobase T is not automatically surface T. For escape/rms ratio six, Lambda is 54, not 36.','Escape is exponentially sensitive to species mass and temperature; an rms comparison alone misses the rare energetic tail.','Nonthermal loss, replenishment and geological timescale matter. Six-rms retention is a heuristic, not a guarantee; the Moon has an exosphere.'))
O('atmospheres','Atmospheres: hydrostatics plus a model','Hydrostatics and gas density are core tools; vertical profiles and parcel stability add assumptions.','Source §7.3; Q21, Q32, Q34; dry/moist and exponent corrections',['atmosphere','lapse'],'An isothermal atmosphere and an adiabatically rising parcel are different thermodynamic models.',
C('Isothermal scale height',[r'dP/dz=-\rho g=-PMg/(RT)',r'P=P_0e^{-z/H},\quad H=RT/(Mg)',r'\rho=\rho_0e^{-z/H}'],'Constant T, g and composition; z increases upward. At about 288 K with M=0.029 kg/mol, H is about 8.4 km. Every scale height divides P by e.','Substituting ideal-gas density into hydrostatic balance produces the exponential rather than a linear pressure fall.','A single constant H cannot accurately describe a whole real atmosphere with changing temperature, gravity or composition. This model has no finite-height zero pressure.'),
C('Dry adiabatic parcel',[r'TP^{(1-\gamma)/\gamma}=\mathrm{constant}',r'dT/dz=-Mg/C_P=-g/c_P',r'\Gamma_d\simeq9.8\ \mathrm{K/km}'],'A dry rising parcel approximately matches ambient pressure and expands adiabatically. CP is molar; cP is per mass. Hydrostatics, the gas equation and the adiabatic derivative give the lapse rate.','Expansion work lowers the parcel\'s internal energy as it rises into lower pressure. Gravity supplies the pressure gradient setting the rate.','The exponent in T times a power of P is NEGATIVE. Do not mix molar capacity with a per-mass formula.'),
C('Dry profile and moist correction',[r'T=T_0-\Gamma_dz',r'P=P_0(T/T_0)^{\gamma/(\gamma-1)}',r'\rho=\rho_0(T/T_0)^{1/(\gamma-1)}'],'The formal zero-temperature height is an extrapolation outside the model, not a physical atmosphere edge. A saturated moist parcel normally cools more gently because condensation releases latent heat.','From the same base temperature, moist ascent usually stays warmer aloft than the dry prediction.','Actual lapse rates vary. One illustrative moist slope is not a universal law; phase change and changing composition require extra equations.'),
C('Stability and balloon modelling',[r'\Gamma_{\rm env}>\Gamma_d:\ \mathrm{dry\ instability}'],'If the environment cools faster than a rising dry parcel, the parcel stays warmer and less dense than its new surroundings and tends to keep rising. At altitude, balloon lift requires recomputing inside/outside densities at local P and T.','Stability compares the parcel response with the ENVIRONMENTAL profile, not merely whether ambient T falls upward.','Moisture and composition gradients modify the dry criterion. Do not combine an isothermal pressure profile with a contradictory ambient temperature profile without a stated approximation.'))
O('real-gases','Real gases: interactions & criticality','Use molar v=V/n. Van der Waals constants a and b describe a particular model.','Source §7.4; Q31; nonideal free-expansion qualification',['vdw','critical'],'The equation of state predicts pressure; a caloric relation is also needed to predict temperature change.',
C('Van der Waals equation',[r'(P+a/v^2)(v-b)=RT',r'P=RT/(v-b)-a/v^2'],'b models excluded molar volume and a attractive interactions. Units: b in m³/mol, a in Pa m^6/mol². Excluded volume raises the repulsive term; attraction lowers the pressure. Their net correction can have either sign.','Finite particle size and intermolecular potential energy are different departures from the ideal-gas model.','The subcritical oscillating loop is not stable coexistence. Do not follow it as a physical equilibrium phase-change trajectory.'),
C('Critical point from derivatives',[r'(\partial P/\partial v)_T=0,\quad(\partial^2P/\partial v^2)_T=0',r'RT/(v-b)^2=2a/v^3',r'2RT/(v-b)^3=6a/v^4',r'v_c=3b,\quad P_c=a/(27b^2)',r'T_c=8a/(27Rb),\quad Z_c=3/8'],'Eliminate RT from the two derivative conditions: 2v=3(v-b), hence vc=3b. Substitute to obtain Pc and Tc.','The critical isotherm has a horizontal inflection where the liquid-vapour distinction ends in this model.','Zc=3/8 is a model prediction, not an exact universal experimental constant.'),
C('Coexistence and measured data',[r'\int_{v_\ell}^{v_g}(P-P_{\rm sat})\,dv=0',r'b=RT_c/(8P_c),\quad a=27P_cb^2'],'Maxwell\'s equal-area construction ensures equal chemical potentials in the two phases. CO2 with Tc about 304 K and Pc about 7.39 MPa gives b about 4.28 times 10^(-5) m³/mol and a about 0.365 Pa m^6/mol².','The coexistence tie line replaces the unstable part; equal-area and equal-pressure endpoints select the saturation pressure together.','A guessed horizontal line need not satisfy coexistence. The plotted line here is solved numerically, not chosen by eye.'),
C('Caloric equation and free expansion',[r'du=C_VdT+[T(\partial P/\partial T)_v-P]dv',r'\Delta u=C_V\Delta T+a(1/v_1-1/v_2)',r'\Delta T=(a/C_V)(1/v_2-1/v_1)'],'Last line: insulated free expansion with constant molar CV in the vdW model. No heat or work crosses the closed outer boundary, so U stays constant.','Separation increases attractive potential energy, paid from thermal energy, giving cooling. Ideal a=0 recovers unchanged T.','Do not call this simultaneously insulated free expansion and isothermal expansion unless a=0 or another energy transfer is specified.'))
O('throttling','Throttling is not free expansion','Steady-flow energy includes flow work. Keep molar and specific quantities consistent.','Source §§3.4, 7.4; Joule-Thomson and dilute inversion limit',['throttle','inversion'],'A throttle conserves enthalpy under stated conditions; closed insulated free expansion conserves internal energy.',
C('Why enthalpy appears in flow',[r'h_1+u_1^2/2+gz_1=h_2+u_2^2/2+gz_2',r'h=u_{\rm int}+Pv'],'Steady adiabatic flow, no shaft work; first line uses h per mass and bulk speed u. If speed and height changes are negligible, h1=h2. Material must be pushed into and out of the control volume.','Flow work P v combines with internal energy into enthalpy. This contribution is absent from a closed fixed-mass vacuum-expansion ledger.','A turbine has shaft work and a nozzle can convert h into bulk kinetic energy; neither is generally an isenthalpic throttle.'),
C('Joule-Thomson sign',[r'\mu_{JT}=(\partial T/\partial P)_h',r'\mu_{JT}=\frac{T(\partial v/\partial T)_P-v}{C_P}'],'For a pressure drop dP<0, positive muJT produces cooling and negative muJT produces warming. An ideal gas has muJT=0 because its enthalpy depends only on temperature.','A pressure reduction alone does not specify temperature change: the conserved quantity and interaction model must be known.','Use molar v with molar CP, or specific v with specific cP. Do not mix units or reverse the sign for a pressure drop.'),
C('Dilute van der Waals limit',[r'v\simeq RT/P+b-a/(RT)',r'\mu_{JT}\simeq[2a/(RT)-b]/C_P',r'T_{i,\rm upper}\simeq2a/(Rb)'],'The last expression is the low-pressure UPPER inversion limit, not a complete pressure-dependent inversion curve. Hydrogen and helium can warm on throttling at room temperature and may need pre-cooling for liquefaction.','Attractive interactions favour cooling while excluded-volume effects can favour warming. Their competition determines the sign.','Do not equate every expansion with cooling or treat the dilute limit as exact at high pressure.'),
C('Keep three energy ledgers apart',[r'\Delta s_{\rm ideal,throttle}=-R\ln(P_2/P_1)>0'],'Closed ideal insulated free expansion: U and T unchanged, entropy rises. Steady ideal throttle: h and T unchanged, entropy rises. Reversible adiabatic turbine: entropy unchanged, h falls and shaft work is produced.','The same pressure ratio can correspond to very different work outputs and different temperature changes depending on the process constraints.','Ideal-gas formulas, low-density inversion limits and reversible power laws have separate validity clauses; they are not interchangeable expansion laws.'))
O('radiation-gas','Photon gas & radiative applications','Ordinary radiation laws are in Part I; photon-gas entropy and adiabats add specialised thermodynamics.','Source §7.5; Q22, Q35; spectral and albedo corrections',['photon','albedo'],'Photon number is not conserved in equilibrium. The radiation 4/3 adiabat is not a naive fixed-mole CP/CV result.',
C('Equilibrium radiation as a fluid',[r'U=a_{\rm rad}T^4V,\quad P=a_{\rm rad}T^4/3',r'a_{\rm rad}=4\sigma/c',r'S=\frac43a_{\rm rad}T^3V'],'Equilibrium black-body photons have zero chemical potential and no conserved particle number. Isotropic photon momentum flux gives pressure one-third of energy density.','With zero chemical potential, TS=U+PV gives the entropy. This differs from a fixed-mole material gas.','The radiation coefficient a(rad) is not the van der Waals attraction constant a. Do not mix their dimensions or interpretations.'),
C('Derive the radiation adiabat',[r'dU=-P\,dV',r'4a_{\rm rad}T^3V\,dT=-\frac43a_{\rm rad}T^4dV',r'TV^{1/3}=\mathrm{constant}',r'PV^{4/3}=\mathrm{constant}'],'For reversible adiabatic expansion, differentiating U and substituting photon pressure gives the temperature-volume relation. If all lengths double, V becomes eightfold and T halves.','Radiation entropy is proportional to T cubed times V, so this expansion keeps S constant.','The formal exponent 4/3 does not justify an ordinary fixed-N heat-capacity-ratio argument for photons.'),
C('Thermal wavelengths follow scale',[r'\lambda_{\max}T=b_W',r'T_f=T_i/\mathcal L,\quad\lambda_f=\mathcal L\lambda_i'],'A 3000 K thermal field redshifted by scale factor 1101 reaches about 2.725 K. Its per-wavelength peak moves from about 966 nm to about 1.06 mm.','Both the adiabatic temperature scaling and Wien\'s law predict the same wavelength scaling, providing a consistency check.','966 nm is infrared, not visible. Peaks of frequency and wavelength spectral densities do not convert by simply substituting nu=c/lambda.'),
C('Albedo: brighter means cooler',[r'T=[S_\odot(1-\mathcal A)/(4\sigma)]^{1/4}',r'dT/T=-d\mathcal A/[4(1-\mathcal A)]'],'At sunlight flux 1361 W/m², albedo 0.30 and black-body emission, effective T is about 254.6 K. Increasing albedo to 0.33 gives about 251.8 K, a reduction about 2.8 K.','Higher albedo means more reflection, so less absorbed sunlight. It is brightening, not darkening.','This uniform radiating-temperature estimate excludes a greenhouse model and is not automatically the surface temperature.'))
O('availability-tanks','Useful work & compressed-tank limits','Specify ambient T0, P0, mass boundary, heat exchange and reference endpoint.','Source Q30, Q36; corrected useful-work and blowdown models',['availability','blowdown'],'A rigid tank losing gas is not a fixed-mass piston. Useful work excludes atmospheric displacement.',
C('Availability is not total work',[r'W_{\rm useful}=W_{\rm total}-P_0\Delta V',r'W_{\rm lost}=T_0S_{\rm gen}'],'Lost work compares processes with appropriate matching endpoints and the same environment. Some expansion work merely makes room against atmospheric pressure and is not available as useful shaft output.','Entropy generation destroys availability, not energy. Naming the environment is essential to quantify the lost useful-work opportunity.','Do not compare arbitrary different final states with one T0 delta S. Availability is a thermodynamic bound, not guaranteed valve or turbine output.'),
C('Isothermal pressure availability',[r'B=P_iV_i\ln(P_i/P_0)-(P_i-P_0)V_i'],'Ideal gas initially at ambient T0, pressure Pi, volume Vi; reversible equilibration to P0,T0 with heat exchange. For 200 atm, 0.050 cubic metres and ambient 1 atm, total closed-gas work is about 5.369 MJ; useful availability about 4.361 MJ or 1.21 kWh.','Subtract atmospheric displacement from logarithmic work. Ideal reversible isothermal tank discharge yields the same availability.','An ordinary throttle recovers no shaft work. Isothermal recovery requires heat supply, not a simultaneous insulated-tank assumption.'),
C('Insulated well-mixed tank discharge',[r'd(nC_VT)=C_PT\,dn',r'T/T_i=(n/n_i)^{\gamma-1}',r'P/P_i=(n/n_i)^\gamma',r'T/T_i=(P/P_i)^{(\gamma-1)/\gamma}'],'Rigid insulated ideal-gas tank, negligible wall thermal capacity, inflow and bulk kinetic energy. Outflow carries enthalpy at the tank temperature; n decreases.','The outgoing mass-energy flux controls cooling. This is an OPEN-system balance, not closed-mass reversible boundary work.','Constant capacities and single-phase gas assumptions may fail at sufficiently low T; the exponent is not gamma-1 for a pressure ratio.'),
C('Do not overclaim phase or safety',[],'At gamma=1.4, ideal blowdown from 200 to 1 atm gives about 66 K, not 36 K. The model reaches 77 K near 1.72 atm, but 77 K is nitrogen\'s ONE-atm boiling point, not an air dew-point calculation. Sealed heating 300 to 320 K gives 200 to 213.3 atm.','Real-air condensation needs composition and a pressure-dependent phase envelope. Safety additionally needs wall temperature, material strength, ratings and relief-system data.','Neither a precise condensation-onset pressure nor fire safety can be certified from these ideal-gas numbers alone.'))
# All prose glyphs must exist in the bundled handwriting font. Equations are separately typeset.
def prose(s):
 s=s.replace('→',' to ').replace('₂','2').replace('₄','4')
 table=str.maketrans('⁰¹²³⁴⁵⁶⁷⁸⁹⁻','0123456789-')
 return re.sub(r'10([⁰¹²³⁴⁵⁶⁷⁸⁹⁻]+)',lambda m:'10^('+m[1].translate(table)+')',s)
for pg in pages:
 for key in ['title','subtitle','source','takeaway']:pg[key]=prose(pg[key])
 for c in pg['cards']:
  c['title']=prose(c['title']);c['items']=[(k,t if k=='m' else prose(t)) for k,t in c['items']]
(ROOT/'sheets.json').write_text(json.dumps(pages,ensure_ascii=False,indent=2)+'\n')
print('Authored',len(pages),'sheets:',sum(p['section']=='JEE' for p in pages),'JEE +',sum(p['section']=='Olympiad' for p in pages),'extensions')
